<?php
declare(strict_types=1);

final class MothershipService
{
    private const MODULES = [
        'volley_bays'=>['column'=>'volley_bays','coefficient'=>12.0,'power_draw'=>3.0,'max'=>50],
        'shield_bays'=>['column'=>'shield_bays','coefficient'=>14.0,'power_draw'=>4.0,'max'=>50],
        'fleet_hangars'=>['column'=>'fleet_hangars','coefficient'=>20.0,'power_draw'=>5.0,'max'=>50],
        'weapons_power'=>['column'=>'weapons_power','coefficient'=>25.0,'power_draw'=>6.0,'max'=>50],
        'shields_power'=>['column'=>'shields_power','coefficient'=>24.0,'power_draw'=>6.0,'max'=>50],
        'exploration_level'=>['column'=>'exploration_level','coefficient'=>10.0,'power_draw'=>2.0,'max'=>50],
    ];
    public function __construct(private PDO $pdo) {}
    private function setting(string $key,int $default=0):int{$s=$this->pdo->prepare('SELECT setting_value FROM game_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:max(0,(int)$v);}
    private function event(int $playerId,int $shipId,string $type,array $payload):void{$s=$this->pdo->prepare('INSERT INTO game_events(player_id,event_type,entity_type,entity_id,payload) VALUES(?,?,?,?,?)');$s->execute([$playerId,$type,'mothership',$shipId,json_encode($payload,JSON_THROW_ON_ERROR)]);}
    private function technologyLevel(int $playerId):int{$s=$this->pdo->prepare("SELECT COALESCE(MAX(level),0) FROM player_technologies WHERE player_id=? AND (technology_key IN ('mothership','command') OR technology_name LIKE '%Mothership%')");$s->execute([$playerId]);return (int)$s->fetchColumn();}
    public function snapshot(int $playerId):array
    {
        if($playerId<1)throw new InvalidArgumentException('Invalid mothership request.');$s=$this->pdo->prepare('SELECT * FROM motherships WHERE player_id=?');$s->execute([$playerId]);$ship=$s->fetch(PDO::FETCH_ASSOC);$states=['ready','locked','insufficient-resource','success','error'];if(!$ship)return ['state'=>'locked','mothership'=>null,'modules'=>[],'queue'=>[],'capacity'=>0,'formula'=>'mothership capacity = hull tier + hangar modules + technology modifier','module_formula'=>'module effect = module level × module coefficient × mothership technology','states'=>$states];$m=$this->pdo->prepare('SELECT module_key,level,durability FROM mothership_modules WHERE mothership_id=? ORDER BY module_key');$m->execute([(int)$ship['id']]);$raw=$m->fetchAll(PDO::FETCH_ASSOC);$techLevel=$this->technologyLevel($playerId);$techModifier=1+($techLevel*0.05);$modules=[];$powerDraw=0;foreach($raw as $module){$key=(string)$module['module_key'];$meta=self::MODULES[$key]??['coefficient'=>10.0,'power_draw'=>2.0,'max'=>50];$level=(int)$module['level'];$effect=$level*(float)$meta['coefficient']*$techModifier;$draw=$level*(float)$meta['power_draw'];$powerDraw+=$draw;$modules[]=['module_key'=>$key,'level'=>$level,'durability'=>(int)$module['durability'],'coefficient'=>(float)$meta['coefficient'],'module_effect'=>round($effect,3),'power_draw'=>round($draw,3),'technology_modifier'=>round($techModifier,3)];}$q=$this->pdo->prepare("SELECT id,module_key,level_before,level_after,starts_at,completes_at,status FROM mothership_upgrade_queue WHERE player_id=? AND status IN ('queued','processing') ORDER BY completes_at");$q->execute([$playerId]);$queue=$q->fetchAll(PDO::FETCH_ASSOC);$capacity=(int)$ship['hull_level']+(int)$ship['fleet_hangars']+$techModifier;return ['state'=>'ready','mothership'=>['id'=>(int)$ship['id'],'name'=>$ship['name'],'hull_level'=>(int)$ship['hull_level'],'volley_bays'=>(int)$ship['volley_bays'],'shield_bays'=>(int)$ship['shield_bays'],'fleet_hangars'=>(int)$ship['fleet_hangars'],'weapons_power'=>(int)$ship['weapons_power'],'shields_power'=>(int)$ship['shields_power'],'exploration_level'=>(int)$ship['exploration_level'],'hull_integrity'=>min(100,(int)$ship['hull_level']*10),'hangar_capacity'=>(int)$ship['fleet_hangars']*100,'shield_strength'=>(int)$ship['shields_power']+(int)$ship['shield_bays']*100,'technology_level'=>$techLevel,'technology_modifier'=>round($techModifier,3),'power_draw'=>round($powerDraw,3),'module_slots_used'=>count($modules),'module_slots_available'=>max(0,(int)$ship['hull_level']+(int)$ship['fleet_hangars']-count($modules))],'modules'=>$modules,'queue'=>$queue,'capacity'=>$capacity,'formula'=>'mothership capacity = hull tier + hangar modules + technology modifier','module_formula'=>'module effect = module level × module coefficient × mothership technology','states'=>$states];
    }
    public function upgrade(int $playerId,string $module):array
    {
        $allowed=array_merge(['hull_level'],array_keys(self::MODULES));if($playerId<1||!in_array($module,$allowed,true))throw new InvalidArgumentException('Invalid mothership module.');$this->pdo->beginTransaction();try{$cooldown=$this->setting('mothership_upgrade_cooldown_seconds');$c=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='mothership_upgrade' FOR UPDATE");$c->execute([$playerId]);$available=$c->fetchColumn();if($available!==false&&new DateTimeImmutable((string)$available)>new DateTimeImmutable('now'))throw new RuntimeException('Mothership upgrade is on cooldown.');$s=$this->pdo->prepare('SELECT * FROM motherships WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);$ship=$s->fetch(PDO::FETCH_ASSOC);if(!$ship)throw new RuntimeException('Mothership not found.');$q=$this->pdo->prepare("SELECT COUNT(*) FROM mothership_upgrade_queue WHERE player_id=? AND status IN ('queued','processing') FOR UPDATE");$q->execute([$playerId]);if((int)$q->fetchColumn()>=3)throw new RuntimeException('Mothership upgrade queue is full.');$before=(int)$ship[$module==='hull_level'?'hull_level':self::MODULES[$module]['column']];$moduleRow=null;if($module!=='hull_level'){$m=$this->pdo->prepare('SELECT level FROM mothership_modules WHERE mothership_id=? AND module_key=? FOR UPDATE');$m->execute([(int)$ship['id'],$module]);$moduleRow=$m->fetch(PDO::FETCH_ASSOC);$before=max($before,(int)($moduleRow['level']??0));if(!$moduleRow){$used=(int)$this->pdo->query('SELECT COUNT(*) FROM mothership_modules WHERE mothership_id='.(int)$ship['id'])->fetchColumn();$slots=(int)$ship['hull_level']+(int)$ship['fleet_hangars'];if($used>=$slots)throw new RuntimeException('No mothership module slots available.');}}$max=$module==='hull_level'?21:self::MODULES[$module]['max'];if($before>=$max)throw new RuntimeException('Mothership module level cap reached.');if($module!=='hull_level'&&$before>0&&(int)$ship['hull_level']<$before)throw new RuntimeException('Mothership hull prerequisite not met.');$cost=25000+($before*10000);$r=$this->pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=? FOR UPDATE');$r->execute([$playerId]);if((int)$r->fetchColumn()<$cost)throw new RuntimeException('Not enough Naquadah.');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$column=$module==='hull_level'?'hull_level':self::MODULES[$module]['column'];$this->pdo->prepare("UPDATE motherships SET {$column}={$column}+1 WHERE player_id=?")->execute([$playerId]);if($module!=='hull_level')$this->pdo->prepare('INSERT INTO mothership_modules(mothership_id,module_key,level,durability) VALUES(?,?,?,100) ON DUPLICATE KEY UPDATE level=VALUES(level),durability=100')->execute([(int)$ship['id'],$module,$before+1]);$seconds=600+($before*60);$start=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');$complete=(new DateTimeImmutable('now'))->modify('+'.$seconds.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO mothership_upgrade_queue(player_id,mothership_id,module_key,level_before,level_after,starts_at,completes_at) VALUES(?,?,?,?,?,?,?)')->execute([$playerId,(int)$ship['id'],$module,$before,$before+1,$start,$complete]);$queueId=(int)$this->pdo->lastInsertId();if($cooldown>0){$next=(new DateTimeImmutable('now'))->modify('+'.$cooldown.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,'mothership_upgrade',$next]);}$tech=$this->technologyLevel($playerId);$coefficient=$module==='hull_level'?1.0:self::MODULES[$module]['coefficient'];$effect=($before+1)*$coefficient*(1+($tech*0.05));$this->event($playerId,(int)$ship['id'],'mothership_module_upgraded',['module'=>$module,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'coefficient'=>$coefficient,'technology_level'=>$tech,'module_effect'=>round($effect,3),'cooldown_seconds'=>$cooldown]);$this->pdo->commit();return ['state'=>'success','mothership_id'=>(int)$ship['id'],'module'=>$module,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'coefficient'=>$coefficient,'technology_level'=>$tech,'module_effect'=>round($effect,3),'cooldown_seconds'=>$cooldown];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
}
